<?php get_header(); ?><main id="primary" class="fsw-main"><div class="fsw-reading"><?php while ( have_posts() ) : the_post(); ?><article <?php post_class(); ?>><header class="fsw-entry-header"><p class="fsw-meta"><?php echo esc_html( get_the_date() ); ?></p><h1 class="fsw-title"><?php the_title(); ?></h1></header><?php if ( has_post_thumbnail() ) : ?><figure><?php the_post_thumbnail( 'large', array( 'loading' => 'eager' ) ); ?></figure><?php endif; ?><div class="fsw-entry-content"><?php the_content(); wp_link_pages(); ?></div><?php if ( comments_open() || get_comments_number() ) { comments_template(); } ?></article><?php endwhile; ?></div></main><?php get_footer(); ?>
